  // ── routes/AboutPage ──────────────────────────────────────────────────────────────
  "أحمد عليوي السفان": "Ахмед Эливи Аль-Саффан",
  "احكي معه متل ما بتحكي مع زميل. بيقرأ الملفات اللي بتشير عليها بـ @، بياخد صور ومرفقات، وعنده أوامر بـ / لتلخيص المحادثة وضبط الرد.":
    "Общайтесь с ним как с коллегой. Он читает файлы, на которые вы указываете через @, принимает изображения и вложения, а команды через / помогают свернуть чат и настроить ответы.",
  "صمّم الواجهة قبل ما تبرمجها: أسئلة brief، مهارات تصميم مدمجة بتشتغل مع أي نموذج، معاينة حيّة، وزر يبعت التصميم للجلسة اللي رح تبرمجه.":
    "Спроектируйте интерфейс до написания кода: вопросы брифа, встроенные навыки дизайна для любой модели, живой предпросмотр и кнопка, отправляющая дизайн в сессию, которая его реализует.",
  "مهامك من Jira و Linear و GitHub و GitLab بمكان واحد. بتغيّر حالتها، بتعلّق عليها، وبتسلّمها لرفيق يشتغل عليها.":
    "Ваши задачи из Jira, Linear, GitHub и GitLab в одном месте. Меняйте статус, комментируйте и передавайте их Rafiq в работу.",
  "أي نموذج": "Любая модель",
  "مش مربوط بشركة وحدة. حط مفتاحك لأي مزوّد، أو شغّل نموذج محلي على جهازك بـ Ollama.":
    "Не привязан к одной компании. Добавьте ключ любого провайдера или запустите локальную модель на своём компьютере через Ollama.",
  "إذنك أولاً": "Сначала ваше разрешение",
  "كل أداة إلها سياسة: اسأل، اسمح، أو امنع. المفاتيح محفوظة بمدير بيانات الاعتماد تبع ويندوز، ومحادثاتك ومهامك على جهازك.":
    "У каждого инструмента своя политика: спрашивать, разрешать или запрещать. Ключи хранятся в диспетчере учётных данных Windows, а ваши чаты и задачи — на вашем компьютере.",
  "افتح صفحة المطوّر على GitHub": "Открыть страницу разработчика на GitHub",
  "انسخ رابط GitHub": "Копировать ссылку на GitHub",
  "مساعد ذكي على ويندوز، بيحكي عربي وبيشتغل على جهازك — مش بس بيجاوب، بيخلّص الشغل.":
    "ИИ-помощник для Windows, который говорит на вашем языке и работает на вашем компьютере — не просто отвечает, а доводит дело до конца.",
  "شو هو رفيق؟": "Что такое Rafiq?",
  "رفيق تطبيق سطح مكتب بيربطك بنماذج الذكاء الاصطناعي اللي بتختارها، وبيعطيها أدوات حقيقية تشتغل فيها: تقرأ وتكتب ملفات، تشغّل أوامر، وتتابع مهامك من أنظمة التتبّع. الواجهة عربية من الأساس ومن اليمين لليسار، والشغل كله بيصير على جهازك وتحت عينك — ما في خطوة حسّاسة بتصير من غير ما توافق عليها.":
    "Rafiq — настольное приложение, которое подключает вас к выбранным моделям ИИ и даёт им настоящие инструменты: чтение и запись файлов, запуск команд и работу с задачами из трекеров. Интерфейс изначально создан на арабском, справа налево, и также доступен на английском и русском. Вся работа идёт на вашем компьютере и у вас на глазах — ничего важного не происходит без вашего согласия.",
  "شو بيعمل": "Что он умеет",
  "بيشتغل مع": "Работает с",
  "المطوّر": "Разработчик",
  "صمّم رفيق وبناه — من الواجهة العربية لمحرّك الوكيل اللي بيشتغل بالخلفية.":
    "Спроектировал и создал Rafiq — от арабского интерфейса до движка агента, работающего в фоне.",
  "مبني بـ Tauri و React و Python": "Создано на Tauri, React и Python",
  "أ": "А",

