  "أول ما النموذج يرجّع أول نسخة من الواجهة رح تشوفها حيّة، وتقدر تناقشه بالشات على اليمين وتشوف التعديل مباشرة.":
    "Как только модель вернёт первую версию интерфейса, вы увидите её вживую, сможете обсудить её в чате рядом и сразу увидеть каждое изменение.",
  "انضافت المهارة {0}": "Навык {0} добавлен",
  "ما قدرت أضيف المهارة": "Не удалось добавить навык",
  "ما قدرت أقرأ المهارة.": "Не удалось прочитать навык.",
  "الصق مهارة": "Вставить навык",
  "أضف مهارة": "Добавить навык",
  "هاي المهارات المدمجة اللي رفيق بيقرأها قبل ما يصمّم وبيرجعلها بكل تعديل. بتشتغل مع أي نموذج لأنها بتنمرّر كأدوات عادية (skill_list و skill_read). بتقدر تضيف مهاراتك بمجلد":
    "Это встроенные навыки, которые Rafiq читает перед проектированием и к которым возвращается при каждой правке. Они работают с любой моделью, потому что передаются как обычные инструменты (skill_list и skill_read). Свои навыки можно добавить в папку",
  "مهارتك": "Ваш",
  "احذف المهارة": "Удалить навык",
  "ما قدرت أحفظ المهارة": "Не удалось сохранить навык",
  "الصق محتوى SKILL.md. إذا ما فيه front matter، رفيق بيضيفه لحاله.": "Вставьте содержимое SKILL.md. Если в нём нет front matter, Rafiq добавит его сам.",
  "اسم المهارة (إنجليزي، بدون مسافات)": "Название навыка (латиницей, без пробелов)",
  "# محتوى المهارة…": "# Содержимое навыка…",
  "احفظ المهارة": "Сохранить навык",
  "انبعت التصميم للمحادثة.": "Дизайн отправлен в чат.",
  "ما قدرت أبعت التصميم": "Не удалось отправить дизайн",
  "بتفتح جلسة برمجة نضيفة ومعها التصميم": "Открывает новую сессию разработки с приложенным дизайном",
  "محادثة موجودة": "Существующий чат",
  "ابعتها لجلسة شغّالة على المشروع": "Отправить в сессию, которая уже работает над проектом",
  "مهمة بالخلفية": "Фоновая задача",
  "ابعت التصميم للبرمجة": "Отправить дизайн в разработку",
  "بينبعت القرارات + كود الواجهة المعتمد، مع تعليمات إنه يقرأ مهارة impeccable قبل ما يبدأ.":
    "Отправляются решения и утверждённый код интерфейса вместе с указанием прочитать навык impeccable перед началом.",
  "النموذج اللي رح يبرمج": "Модель, которая будет писать код",
