  "ما قدرت أجيب التصاميم": "Не удалось загрузить дизайны",
  "تصميم جديد": "Новый дизайн",
  "صمّم الواجهة قبل ما تبرمجها: رفيق بيسألك أسئلة الـ brief، بيقرأ مهارات التصميم المدمجة، بيعطيك معاينة حيّة تناقشه فيها، ولما تجهز بتبعتها للجلسة اللي رح تبرمجها.":
    "Спроектируйте интерфейс до написания кода: Rafiq задаёт вопросы брифа, читает встроенные навыки дизайна, показывает живой предпросмотр для обсуждения, а когда всё готово, вы отправляете его в сессию, которая его реализует.",
  "ما في تصاميم بعد. اضغط «تصميم جديد»، ابنِ هوية تطبيقك البصرية وجاوب على أسئلة عن المنتج — بعدها بتفتحلك جلسة تصميم فيها شات ومعاينة حيّة.":
    "Дизайнов пока нет. Нажмите «Новый дизайн», создайте визуальную айдентику приложения и ответьте на вопросы о продукте — после этого откроется сессия дизайна с чатом и живым предпросмотром.",
  "افتح التصميم": "Открыть дизайн",
  "انسخ كود الواجهة": "Копировать код интерфейса",
  "احذف التصميم": "Удалить дизайн",
