  "مدمجة بالتطبيق — ما بدها تنزيل ولا إعداد، وبتشتغل مع أي نموذج (رفيق بيمرّرها كأدوات عادية، مو كميزة خاصة بمزوّد).":
    "Встроены в приложение — ничего не нужно скачивать и настраивать, и работают с любой моделью (Rafiq передаёт их как обычные инструменты, а не как функцию конкретного провайдера).",
  "ما قدرت أجيب الأسئلة": "Не удалось загрузить вопросы",
