  "عم يتصل…": "Подключение…",
  "متصل · {0} أداة": { one: "Подключено · {0} инструмент", few: "Подключено · {0} инструмента", many: "Подключено · {0} инструментов", other: "Подключено · {0} инструмента" },
  "ما اتصل لسا — بيتصل أول ما الوكيل يحتاجه.": "Ещё не подключён — подключится, как только понадобится агенту.",
  "اختبر": "Проверить",
  "عدّل": "Изменить",
  "مفعّل": "Включено",
  "مراجعة الكود": "Ревью кода",
  "راجع الكود بهالمجلد: دوّر على الأخطاء، المشاكل الأمنية، والأشياء اللي ممكن تتبسّط. رتّبها حسب الأهمية، وما تعدّل ولا ملف — بس اكتب تقرير.": "Проверь код в этой папке: найди ошибки, проблемы безопасности и то, что можно упростить. Расставь по важности и не меняй ни одного файла — только напиши отчёт.",
  "كتابة اختبارات": "Написать тесты",
  "اكتب اختبارات للأجزاء المهمة بالمشروع اللي ما عليها اختبارات، شغّلها، وتأكد إنها بتنجح. قلّي شو غطّيت وشو ضل.": "Напиши тесты для важных частей проекта, у которых их нет, запусти их и убедись, что они проходят. Расскажи, что покрыто и что осталось.",
  "تحديث README": "Обновить README",
  "اقرأ المشروع وحدّث ملف README ليشرح شو بيعمل، كيف ينثبت ويشتغل، وكيف تنعمل المساهمة. لا تخترع ميزات مو موجودة.": "Изучи проект и обнови README: что он делает, как его установить и запустить и как внести вклад. Не выдумывай несуществующих функций.",
  "ترتيب الملفات": "Навести порядок в файлах",
  "رتّب الملفات بهالمجلد بمجلدات منطقية حسب النوع أو الموضوع، وما تحذف شي. اكتبلي ملخص باللي نقلته ولوين.": "Разложи файлы в этой папке по понятным папкам по типу или теме и ничего не удаляй. Напиши, что и куда ты переместил.",
  "كل {0} ساعة": { one: "Каждый {0} час", few: "Каждые {0} часа", many: "Каждые {0} часов", other: "Каждые {0} часа" },
  "كل {0} دقيقة": { one: "Каждую {0} минуту", few: "Каждые {0} минуты", many: "Каждые {0} минут", other: "Каждые {0} минуты" },
