  "احفظ الجدولة": "Сохранить расписание",
  "مهام بتبلش لحالها بوقتها. رفيق لازم يكون شغّال (ولو بالخلفية بجنب الساعة)؛ الموعد اللي بيفوت وهو مسكّر بيشتغل مرة وحدة أول ما يفتح.": "Задачи, которые запускаются сами в нужное время. Rafiq должен быть запущен (хотя бы в фоне, рядом с часами); пропущенный, пока он был закрыт, запуск выполнится один раз при открытии.",
  "جدولة جديدة": "Новое расписание",
  "ما في مهام مجدولة. مثلاً: «كل يوم الساعة 9 لخّصلي مهامي الجديدة»، أو «كل جمعة راجع التبعيات».": "Запланированных задач нет. Например: «каждый день в 9 кратко опиши мои новые задачи» или «каждую пятницу проверяй зависимости».",
  "الجاية: {0}": "Следующий: {0}",
