  "ملف واحد فيه كل شي — الردود والأدوات والصور — بيتفتح بأي متصفح وبالوضعين الفاتح والداكن. للمشاركة.": "Один файл со всем — ответы, инструменты, изображения — открывается в любом браузере, светлая и тёмная тема. Для отправки другим.",
