  "/راجع": "/review",
  "مراجعة كود مجلد المحادثة: أخطاء، أمان، أداء": "Ревью кода в папке чата: ошибки, безопасность, производительность",
  "راجع": "review",
  "مراجعة": "ревью",
  "راجع الكود بهالمجلد: ركّز على الأخطاء المنطقية، الحالات الحدّية، مشاكل الأمان، والأداء. لكل ملاحظة اذكر الملف والسطر واقتراح الإصلاح. لا تعدّل شي، بس اكتب التقرير.": "Проведи ревью кода в этой папке: логические ошибки, граничные случаи, безопасность и производительность. Для каждого замечания укажи файл, строку и предлагаемое исправление. Ничего не меняй — только отчёт.",
