  "كل مشروع بمجلده ونموذجه وتعليماته. لما تختار مساحة، المحادثات والمهام والتصاميم بتتصفّى عليها والجلسات الجديدة بتبلّش بإعداداتها.": "У каждого проекта своя папка, модель и инструкции. Выберите пространство — чаты, задачи и дизайны отфильтруются по нему, а новые сессии начнутся с его настроек.",
