  "بتنضاف لكل محادثة ومهمة بهالمساحة — مثلاً: «المشروع بـ TypeScript، لا تستخدم any، الرد بالعربي».": "Добавляются к каждому чату и задаче в этом пространстве — например: «Проект на TypeScript, не использовать any, отвечать по-арабски».",
