  "النسخة الكاملة من impeccable.style — مسارات audit وpolish وcritique وغيرها لمراجعة التصميم وتحسينه.": "Полный навык impeccable.style — audit, polish, critique и другие сценарии для ревью и улучшения дизайна.",
  "مراجعة الواجهة على قواعد Vercel: وصولية، أداء، نماذج، وحركة.": "Проверка интерфейса по правилам Vercel: доступность, производительность, формы и анимация.",
  "مهارة Anthropic لواجهات مميّزة بعيدة عن الشكل «الجاهز» — اتجاه بصري واضح وتفاصيل مدروسة.": "Навык Anthropic для выразительных интерфейсов без «шаблонного» вида — ясное визуальное направление и продуманные детали.",
  "قاعدة كبيرة من أنماط الواجهات، لوحات ألوان، وأزواج خطوط حسب نوع المنتج.": "Большая база UI-паттернов, палитр и пар шрифтов по типу продукта.",
  "مهاراتك": "Ваши навыки",
  "نزّل من رابط": "Установить по ссылке",
  "مستودع GitHub كامل، مجلد جوّاه، ملف SKILL.md مباشر، أو zip. المستودع اللي فيه أكتر من مهارة بينزّلوا كلهم. بس ملفات نصية بتتنزّل — ما في شي بيتنفّذ.": "Целый репозиторий GitHub, папка внутри него, файл SKILL.md или zip. Из репозитория с несколькими навыками установятся все. Скачиваются только текстовые файлы — ничего не выполняется.",
  "مهارات تصميم مقترحة": "Рекомендуемые навыки дизайна",
  "منزّلة": "Установлен",
  "نزّلها": "Установить",
  "ملاحظة: المهارات نصوص بس وما بدها Node.js — بس بعض مهارات التصميم بتشغّل أوامر npx بمشروعك، وهاي بتحتاجه.": "Примечание: навыки — это текст, Node.js им не нужен, но некоторые навыки дизайна запускают npx в проекте, и им он нужен.",
  "أوامر / من المهارات": "Slash-команды из навыков",
  "اكتبها بصندوق أي محادثة — كل أمر بيبعت تعليمات المهارة للنموذج.": "Вводите их в любом чате — каждая отправляет инструкции навыка модели.",
