  "النموذج بيقرأها لحاله لما تلزم (skill_read)، وبتقدر تذكرها بالاسم بأي محادثة.": "Модель прочитает его сама при необходимости (skill_read), а вы можете упомянуть его по имени в любом чате.",
  "تمام": "Готово",
  "لما تقول لرفيق «تذكّر إني…» بيحفظها هون، وبيشوفها بكل محادثة ومهمة جاية. كل حفظ بيمرّ من صلاحية «الذاكرة» فبتشوف شو رح ينحفظ قبل ما ينحفظ، وبتقدر تعدّل أو تحذف أي شي بأي وقت.": "Когда вы говорите Rafiq «запомни, что я…», это сохраняется здесь и видно в каждом следующем чате и задаче. Каждое сохранение проходит через разрешение «Память», так что вы видите, что будет сохранено, и можете изменить или удалить что угодно.",
