  "اتصل ✓": "Подключено ✓",
  "اربط خدماتك (GitHub، Notion، Linear، قواعد بيانات…) وأدواتها بتصير متاحة للوكيل بالمحادثات والمهام، وكل استدعاء بيمرّ من صلاحية «أدوات MCP». التوكنات وتسجيلات الدخول بتنحفظ بـ Windows Credential Manager.": "Подключите свои сервисы (GitHub, Notion, Linear, базы данных…) — их инструменты появятся в каждом чате и задаче; каждый вызов проходит через разрешение «Инструменты MCP». Токены и входы хранятся в Windows Credential Manager.",
