  "وضع اقتصادي": "Экономичный режим",
  "أرخص رد ممكن: بدون أدوات ولا تفكير، ورد قصير. للأسئلة اللي جوابها من معرفة النموذج.": "Самый дешёвый ответ: без инструментов, без рассуждений, коротко. Для вопросов, на которые модель отвечает из своих знаний.",
  "أدوات المتصفح": "Инструменты браузера",
  "ست أدوات للتصفّح والضغط والكتابة. طفّيها إذا هالمحادثة ما بدها متصفح.": "Шесть инструментов для навигации, кликов и ввода. Выключите, если в этом чате браузер не нужен.",
  "أدوات خوادم MCP": "Инструменты серверов MCP",
  "خادم واحد ممكن يضيف عشرات الأدوات لكل رسالة. طفّيها لما ما تلزم.": "Один сервер может добавлять десятки инструментов к каждому сообщению. Выключите, когда они не нужны.",
  " · {0} منها مخزّنة": " · из них в кэше: {0}",
  "{0} توكن دخل · {1} خرج": "{0} токенов на вход · {1} на выход",
  "موديل الشغل الداخلي": "Модель для внутренней работы",
  "رفيق بيستخدمه لشغله هو: تلخيص المحادثات الطويلة وكتابة رسائل الـ commit. خلّيه موديل رخيص — هالشغل ما بده ذكاء الموديل الغالي.": "Используется для собственных задач Rafiq: сворачивание длинных чатов в резюме и написание сообщений коммитов. Выберите дешёвую модель — здесь не нужна дорогая.",
  "توفير التوكنز": "Экономия токенов",
  "بيبعت أسماء المهارات بس، والنموذج بيقرأ اللي بدّه ياه بنفسه. طفّيه لما تشتغل على التصميم أو بدك النموذج يشوف وصف كل مهارة بكل رسالة.": "Отправляет только названия навыков — модель сама читает нужные. Выключите для работы над дизайном или если хотите описание каждого навыка в каждом сообщении.",
  "بيبعت أسماء المهارات بس بدل وصف كل وحدة — بيوفّر آلاف الأحرف بكل رسالة. هاد الافتراضي للمحادثات الجديدة، وكل محادثة بتقدر تغيّره من /إعدادات.": "Отправляет названия навыков вместо описания каждого — тысячи символов экономии в каждом сообщении. Это значение по умолчанию для новых чатов; любой чат может изменить своё в /настройки.",
  "محادثات": "чатов",
  "رسائل": "сообщений",
  "نماذج": "моделей",
