  "نسخة احتياطية": "Резервная копия",
  "احفظ كل شي بملف واحد": "Сохранить всё в один файл",
  "المحادثات والمهام والإعدادات والنماذج والذاكرة والمهارات اللي نزّلتها والمرفقات. المفاتيح وكلمات السر ما بتنحط فيه أبداً.": "Чаты, задачи, настройки, модели, память, установленные навыки и вложения. Ключи и пароли в неё никогда не попадают.",
