  "عبّي: {0}": "Заполните: {0}",
  "مراجعة فرع": "Ревью ветки",
  "راجع التغييرات على الفرع {{branch}} مقارنة مع {{base}}: الأخطاء، المشاكل الأمنية، والاختبارات الناقصة. لا تعدّل شي — اكتب تقرير مرتب حسب الأهمية.": "Проверь изменения в ветке {{branch}} относительно {{base}}: ошибки, проблемы безопасности и недостающие тесты. Ничего не меняй — напиши отчёт, отсортированный по важности.",
  "حط {0} مكان اللي بيتغير كل مرة — مثل {{folder}} أو {{branch}}. رفيق بيسألك عنه لما تستخدم القالب، والمجلد والفرع والتاريخ بيتعبّوا لحالهم.": "Пишите {0} там, где текст каждый раз меняется, — например {{folder}} или {{branch}}. Rafiq спросит значение при использовании шаблона; папка, ветка и дата подставляются сами.",
  "بيسألك عنهن قبل ما تبلّش المهمة": "Их спросят перед запуском задачи",
  "عبّي الأجزاء اللي بتتغير": "Заполните меняющиеся части",
  "القالب فيه فراغات — بينحطوا مكانها بالمهمة قبل ما تبلّش.": "В шаблоне есть пропуски — они подставятся в задачу перед запуском.",
  "مطلوب": "обязательно",
  "استعلامات وتعديلات على قاعدة Postgres — كل تعديل بياخد إذنك.": "Запросы и изменения в базе Postgres — каждое изменение требует вашего разрешения.",
  "بدون كلمة المرور — إلها خانتها لحالها. إذا لصقت رابط فيه كلمة مرور، رفيق بيشيلها منه وبيحفظها بالخانة.": "Без пароля — для него есть отдельное поле. Если вставить ссылку с паролем, Rafiq уберёт его оттуда и сохранит в это поле.",
  "كلمة المرور": "Пароль",
  "بتنحفظ بخزنة ويندوز (Credential Manager)، مش مع إعدادات الخادم. اتركها فاضية إذا القاعدة ما بدها كلمة مرور.": "Хранится в хранилище Windows (Credential Manager), а не в настройках сервера. Оставьте пустым, если пароль не нужен.",
  // Workspace budgets
  "اليوم {0} · بلا حد": "Сегодня {0} · без лимита",
  "وصل الحد: {0} من {1}": "Лимит исчерпан: {0} из {1}",
  "اليوم {0} من {1}": "Сегодня {0} из {1}",
  "حد المصروف اليومي (اختياري)": "Дневной лимит расходов (необязательно)",
  "لما محادثات ومهام هالمساحة يصرفوا هالمبلغ باليوم، رفيق بيوقف يبعت للنماذج منها لبكرا — والباقي بيكمّل عادي. فاضي = بلا حد.": "Когда чаты и задачи этого пространства потратят эту сумму за день, Rafiq перестанет отправлять их моделям до завтра — остальное работает как обычно. Пусто — без лимита.",
  "حد لكل مساحة عمل": "Лимит для каждого пространства",
  "فوق الحد العام: كل مساحة إلها مصروفها اليومي. لما توصل حدها، محادثاتها ومهامها بتوقف لبكرا والباقي بيكمّل.": "Поверх общего лимита: у каждого пространства свой дневной расход. Когда пространство достигает лимита, его чаты и задачи ждут до завтра, а остальное продолжает работать.",
