  "ضيف مفتاح Unsplash أو Pexels من الإعدادات ← الفيديو لتدوّر على صور مجانية (المصدر بينحفظ مع الصورة).": "Добавьте ключ Unsplash или Pexels в «Настройки → Видео», чтобы искать бесплатные фото (источник сохраняется вместе с фото).",
