  "أشكال ونصوص كمسارات (العربي سليم بكل مشغّل). بعد التصدير بيتشغّل الملف وبيتقارن مع الإنجن فريم فريم قبل ما ينحفظ.": "Фигуры и текст в виде контуров (арабский текст корректен в любом плеере). После экспорта файл проигрывается и сверяется с движком кадр за кадром, прежде чем сохраниться.",
