  "الألوان والخطوط الوحيدة اللي بيستعملها رفيق بالفيديوهات. كل مساحة عمل بتقدر يكون إلها هوية خاصة، وإلا بتاخد هوية التطبيق.": "Единственные цвета и шрифты, которые Rafiq использует в видео. У каждого рабочего пространства может быть свой стиль, иначе берётся стиль приложения.",
