  "نزّله": "Загрузить",
  "صيغ فيديو إضافية": "Дополнительные форматы видео",
  "التصدير العادي (MP4) ما بده شي. FFmpeg بيضيف H.265 لما الجهاز ما بيدعمه لحاله، وبيفتح فيديوهات بصيغ صعبة (ProRes وMKV و10-bit) بنسخة عمل — نسخة LGPL رسمية، بتنحمّل لما تطلبها ومنتأكد من بصمتها قبل ما تنستعمل.": "Обычный экспорт (MP4) ничего не требует. FFmpeg добавляет H.265, когда компьютер не умеет его сам, и открывает сложные форматы (ProRes, MKV и 10-bit) как рабочую копию — официальная сборка LGPL, загружается по вашему запросу и проверяется по отпечатку перед использованием.",
  "مثبّت": "Установлено",
  "المشفّرات اللي اشتغلت على جهازك:": "Кодировщики, сработавшие на вашем компьютере:",
  "النظر بالصور": "Зрение",
  "موديل بيشوف الإطارات": "Модель, которая смотрит на кадры",
  "لما موديل المحادثة ما بيقدر يشوف صور، رفيق بيبعت إطارات الفيديو لهالموديل ليوصفها، وبيرجّع الوصف للمحادثة.": "Когда модель чата не видит изображения, Rafiq отправляет кадры видео этой модели для описания и передаёт описание обратно в чат.",
  "ولا واحد": "Нет",
  "ريل 9:16": "Рилс 9:16",
  "مربع 1:1": "Квадрат 1:1",
  "بوست 4:5": "Пост 4:5",
  "عريض 16:9": "Широкий 16:9",
  "هوية مساحة العمل": "Стиль пространства",
  "مشروع موشن جديد": "Новый моушн-проект",
  "مثلاً: ريل إطلاق القهوة": "например: рилс запуска кофе",
  "النسبة": "Пропорции",
  "المدة (ثواني)": "Длительность (секунды)",
  "الهوية": "Стиль",
  "شو بدك تعمل؟ (اختياري)": "Что вы хотите сделать? (необязательно)",
  "مثلاً: ريل 12 ثانية لقهوة مختصة، سعر 25 ريال، وزر «اطلب اليوم» بالآخر": "например: рилс на 12 секунд для спешелти-кофе, цена 25 риалов, в конце кнопка «Закажите сегодня»",
  "ما قدرت أجيب المشاريع": "Не удалось загрузить проекты",
  "فيديوهات وموشن قرافك بالشات: الموديل بيكتب المشهد، والإنجن بيرسمه ويفحصه ويصدّره على كرت الشاشة. بتعدّل بالشات أو بالـ timeline، وكل تعديل نسخة.": "Видео и моушн-графика из чата: модель пишет сцену, а движок рисует, проверяет и экспортирует её на видеокарте. Редактируйте в чате или на таймлайне; каждое изменение — новая версия.",
  "مشروع جديد": "Новый проект",
  "ما في مشاريع موشن بعد. ابدأ مشروع جديد واحكي للموديل شو بدك — ريل، إنترو، شرح، أو عدّل فيديو عندك.": "Моушн-проектов пока нет. Создайте новый и расскажите модели, что нужно — рилс, интро, объяснение или монтаж вашего видео.",
  "افتح المشروع": "Открыть проект",
  "احذف المشروع": "Удалить проект",
  "مصدَّر": "Экспортировано",
  "ما لقيت المشروع": "Проект не найден",
  "راجع وحسّن": "Проверить и улучшить",
  "كل المشاريع": "Все проекты",
  "راجع الفيديو لقطة لقطة متل مخرج: شغّل motion_review، وصلّح ملاحظات كل لقطة بـ patch وحدة للقطة، وقارن مع مثال الفيديو الاحترافي. أعد motion_review لحد ما تخلص الملاحظات، وإذا بتشوف صور شوف كمان هالفريمات بـ motion_render_frames: {times}. بالآخر قلّي شو غيّرت بكل لقطة.": "Проверь видео кадр за кадром, как режиссёр: запусти motion_review, исправь замечания по каждому кадру одним патчем на кадр и сравни с примером профессионального видео. Запускай motion_review снова, пока замечаний не останется, а если ты видишь изображения, посмотри ещё эти кадры через motion_render_frames: {times}. В конце расскажи, что изменил в каждом кадре.",
  "رجوع للمشاريع": "К проектам",
