  "تعديل الفيديوهات": "Редактирование видео",
  "تعديل مشهد الفيديو، فحصه، ورسم إطاراته — كله داخل المشروع": "Изменять сцену видео, проверять её и рисовать кадры — всё внутри проекта",
  "تعليق صوتي، تفريغ كلام، صور من Unsplash/Pexels، توليد صور — بيروح لخدمة برّا": "Озвучка, расшифровка речи, фото из Unsplash/Pexels, генерация изображений — уходит во внешний сервис",
