  "موسيقى ومؤثرات على اللحظات المهمة": "Музыка и эффекты на ключевых моментах",
  "ضيف موسيقى بتناسب جو الفيديو، ومؤثرات صوتية على اللحظات المهمة بس (القطع، ظهور العنوان، الزر).": "Добавь музыку под настроение видео и звуковые эффекты только на ключевых моментах (склейки, появление заголовка, кнопка).",
  "/مدة": "/длина",
