  "شغّل الفيديو على كامل الشاشة": "Воспроизвести видео на весь экран",
  "شغل": "играть",
  "صدّر الفيديو MP4": "Экспортировать видео в MP4",
  "مراجعة المصمم قسم قسم، وتصليح الملاحظات": "Проверка дизайнера по разделам и исправление замечаний",
  "راجع التصميم قسم قسم متل مصمم محترف: شغّل design_review، وصلّح كل ملاحظاته، وقارن مع مثال التصميم الاحترافي بالدليل. أعد design_review لحد ما تخلص الملاحظات، وبالآخر قلّي شو غيّرت بكل قسم.": "Проверь дизайн по разделам, как профессиональный дизайнер: запусти design_review, исправь все замечания и сравни с примером профессионального дизайна из руководства. Запускай design_review снова, пока замечаний не останется, и в конце расскажи, что изменил в каждом разделе.",
  "/حركة": "/анимация",
  "ظهور مع السكرول، hover، وحركة بالهيرو": "Появление при прокрутке, hover и движение в hero",
  "تحريك": "движение",
  "أنيميشن": "анимации",
  "ضيف حركة للتصميم متل المواقع الاحترافية: ظهور الأقسام مع السكرول بتتابع، hover على الأزرار والكروت، وحركة بتلفت النظر بالهيرو — بدون مبالغة، ومع prefers-reduced-motion.": "Добавь в дизайн движение, как на профессиональных сайтах: последовательное появление разделов при прокрутке, hover на кнопках и карточках и заметное движение в hero — без перебора и с prefers-reduced-motion.",
  "غيّر ألوان التصميم": "Изменить цвета дизайна",
  "غيّر ألوان التصميم لتكون ": "Сделай цвета дизайна ",
