  "صفحة": "страница",
  "ضيف صفحة جديدة بنفس التدفّق: ": "Добавь новую страницу в тот же сценарий: ",
  "/موبايل": "/мобильный",
  "راجع التصميم على عرض الموبايل": "Проверить дизайн на ширине телефона",
  "جوال": "телефон",
  "راجع التصميم على عرض 380px: صلّح أي شي مكسور أو مزحوم أو مقصوص، وخلّي الأزرار مريحة للمس.": "Проверь дизайн на ширине 380px: исправь всё сломанное, тесное или обрезанное и сделай кнопки удобными для нажатия.",
  "/داكن": "/тёмная",
  "وضع داكن بنفس الهوية": "Тёмная тема в том же стиле",
  "ليلي": "ночь",
  "ضيف وضع داكن بنفس هوية التصميم (مش مجرد قلب ألوان)، مع زر تبديل بيتذكّر اختيار المستخدم.": "Добавь тёмную тему в фирменном стиле дизайна (а не просто инверсию цветов) с переключателем, который запоминает выбор пользователя.",
  "/برمج": "/код",
  "سلّم التصميم لجلسة برمجة": "Передать дизайн в сессию программирования",
