  "حسّن": "доработай",
  "أسئلة عن المنتج. اللي بتتركه فاضي رفيق بيفترضه وبيقلّك شو افترض.": "Вопросы о продукте. Что оставите пустым, Rafiq додумает и скажет, что предположил.",
  "ألوان الداكن": "Цвета тёмной",
  "ألوان الفاتح": "Цвета светлой",
  "ابدأ الآن": "Начать",
  "ابدأ من أسلوب (وعدّل كل شي بعدين)": "Начните со стиля (и потом измените что угодно)",
  "ابنِ ألوان وخطوط وشكل تطبيقك قبل ما يبدأ النموذج — هو بيصمّم بهويتك، مش بقالب.": "Задайте цвета, шрифты и форму вашего приложения до того, как начнёт модель — она проектирует в вашем стиле, а не по шаблону.",
  "اختار هوية أو احفظ وحدة جديدة": "Выберите айдентику или сохраните новую",
  "اختياري": "необязательно",
  "اسم المنتج / الشعار": "Название продукта / логотип",
  "تأكد إن التصميم مش AI slop: شغّل design_slop_check، واقرأ الصفحة قسم قسم مقابل الدليل اللي معه (الألوان، الخطوط، التكوين، النصوص، الصور، الحركة). صلّح كل علامة بتلاقيها بدون ما تطلع عن الهوية، وأعد الفحص لحد ما ما يضل شي. بالآخر قلّي شو العلامات اللي لقيتها وشو عملت بدالها.": "Убедись, что дизайн не выглядит как AI slop: запусти design_slop_check и прочитай страницу по разделам, сверяясь с руководством, которое он вернёт (цвет, шрифты, композиция, тексты, изображения, движение). Исправь каждый признак, не выходя за рамки айдентики, и повторяй проверку, пока ничего не останется. В конце расскажи, какие признаки нашёл и что сделал вместо них.",
  "/آلي": "/slop",
  "تأكد إن التصميم مش AI slop وصلّح علاماته": "Проверить, что дизайн не AI slop, и исправить признаки",
  "آلي": "машинный",
  "سلوب": "слоп",
  "مصطنع": "искусственный",
  "حديث": "Гротеск",
  "كلاسيكي": "С засечками",
