  "دوّر على خط…": "Поиск шрифта…",
  "فيه عربي": "С арабским",
  "ما في خط بهالاسم": "Шрифта с таким названием нет",
  "اقتراح النموذج — عدّل اللي بدك": "Предложение модели — меняйте что угодно",
