  "{0} خط من Google Fonts. خط العناوين إذا ما فيه عربي، الحروف العربية بتطلع بخط النص.": "{0} шрифтов Google Fonts. Если в шрифте заголовков нет арабского, арабские буквы берутся из основного шрифта.",
  "من تصاميم عجبتك": "Из понравившихся дизайнов",
  "روابط أو لقطات شاشة، والنموذج بيقرر": "Ссылки или скриншоты — модель решает",
  "ما قدرت أبني الهوية": "Не удалось собрать айдентику",
  "هوية من تصاميم عجبتك": "Айдентика из понравившихся дизайнов",
  "حط روابط مواقع أو لقطات شاشة أو صفحات محفوظة عجبك شكلها. رفيق بيقيس ألوانها وخطوطها وزواياها وحركتها، والنموذج بيقرر هوية بتجمع ذوقها — وبعدها بتعدّل عليها متل ما بدك.": "Добавьте ссылки, скриншоты или сохранённые страницы, внешний вид которых вам нравится. Rafiq измерит их цвета, шрифты, скругления и движение, а модель предложит айдентику в их духе — дальше меняйте её как хотите.",
  "روابط (كل رابط بسطر)": "Ссылки (по одной в строке)",
  "لقطات شاشة أو ملفات HTML و CSS": "Скриншоты или файлы HTML и CSS",
  "اسحب الصور لهون، أو اضغط لتختار، أو الصق لقطة شاشة (Ctrl+V)": "Перетащите изображения сюда, нажмите, чтобы выбрать, или вставьте скриншот (Ctrl+V)",
  "شو عجبك فيها؟ (اختياري)": "Что вам в них нравится? (необязательно)",
  "مثلاً: الألوان الداكنة من الأول، والخط العريض من التاني، بس أهدى بالحركة": "Например: тёмные цвета первого, жирный шрифт второго, но движение спокойнее",
  "في مواقع بتبني ألوانها بالجافاسكربت فما بتبين كاملة من الرابط — ضيف معها لقطة شاشة. النماذج اللي ما بتشوف صور بتاخد ألوان اللقطات مقاسة، ووصفها من نموذج الرؤية إذا مختاره بالإعدادات.": "Некоторые сайты задают цвета через JavaScript, и по ссылке видны не все — добавьте и скриншот. Модели, которые не видят изображения, получают измеренные цвета скриншотов и описание от модели зрения, если она выбрана в настройках.",
