  "لما تقول «نفّذها» على مهمة، أو الموديل يشتغل على مهمة من هالحساب، هيك بيمشيها رفيق:": "Когда вы нажимаете «Выполнить» или модель работает над задачей из этого аккаунта, Rafiq ведёт её так:",
  "لما يبلّش": "При старте",
