  "لما يخلص": "По завершении",
  "انقلها للمراجعة": "Перевести на ревью",
  "اسم حالة المراجعة": "Название статуса ревью",
  "الكلمة اللي بيحتويها اسم الحالة عندكم (review، QA، testing…)": "Слово из названия статуса ревью (review, QA, testing…)",
  "راقب هالحساب": "Следить за аккаунтом",
  "رفيق بيطّلع كل شوي على مهامك والإشارات وطلبات المراجعة، وبيعلمك بالجديد": "Rafiq регулярно проверяет задачи, упоминания и запросы на ревью и сообщает о новом",
  "كل قديش": "Как часто",
  "أقل من هيك بيصرف من حد الطلبات عند المنصّة": "Чаще — расходует лимит запросов трекера",
  "علّمني عن": "Сообщать о",
  "إشعار ويندوز": "Уведомление Windows",
  "غير الإشعار جوّا التطبيق": "Помимо уведомления в приложении",
  "كل مشروع وين موجود على جهازك — «نفّذها» بتفتح التاسك بالمجلد الصح لحالها.": "Где каждый проект лежит на компьютере — «Выполнить» сама откроет задачу в нужной папке.",
  "لما تنسندلك مهمة جديدة بتطابق قاعدة، رفيق بيحضّرلها تاسك. «خطة أولاً» بتستنى موافقتك قبل ما يعدّل شي.": "Когда новая назначенная задача подходит под правило, Rafiq готовит для неё задачу. «Сначала план» ждёт вашего одобрения.",
  "بحث محفوظ بلغة المنصّة (JQL، بحث GitHub، WIQL…) — بيطلع كتبويب بصفحة «شغلي».": "Сохранённый поиск на языке трекера (JQL, поиск GitHub, WIQL…) — появляется вкладкой в «Моя работа».",
  "قراءة بس": "Только чтение",
  "رفيق بيقرأ من هالحساب بس — لا تعليق ولا تعديل ولا نقل حالة، لا منك ولا من الموديل": "Rafiq только читает этот аккаунт — без комментариев, правок и смены статусов, ни от вас, ни от модели",
  "كل تعديل بيعمله رفيق بينسجّل تحت بـ «شو عدّل رفيق»، وفيك تتراجع عنه وين ما المنصّة بتسمح.": "Каждое изменение Rafiq видно в «Что изменил Rafiq», и его можно отменить, где трекер позволяет.",
