  "شو عدّل رفيق": "Что изменил Rafiq",
  "كل تعليق ونقل حالة وتعديل عمله رفيق على المنصّات، ومين طلبه.": "Каждый комментарий, смена статуса и правка Rafiq в трекерах — и кто попросил.",
  "ملخص الصبح": "Утренняя сводка",
  "كل يوم 8:30": "Каждый день в 8:30",
  "ملخص الصبح من المهام": "Утренняя сводка по задачам",
  "اعملي ملخص الصبح من كل الحسابات المربوطة: استعمل issue_list و issue_reviews و issue_notices. رتّبه: المتأخر، المستحق اليوم، الجديد من مبارح، وطلبات المراجعة. اقترح شو أبلّش فيه أولاً. إذا في قناة فريق مربوطة اسمها فيها «صبح» أو «daily»، ابعته عليها بـ notify_post.": "Сделай утреннюю сводку по всем подключённым аккаунтам: используй issue_list, issue_reviews и issue_notices. Порядок: просроченное, срок сегодня, новое со вчера, запросы на ревью. Подскажи, с чего начать. Если есть подключённый канал команды с «утро» или «daily» в названии, отправь туда через notify_post.",
  "أيام الشغل 9:00": "Рабочие дни в 9:00",
  "Stand-up اليومي": "Ежедневный стендап",
  "اكتبلي stand-up: شو خلص مبارح (task_list للمهام اللي خلصت آخر 24 ساعة، و issue_search للمهام المسندة إلي اللي تحدّثت)، شو رح أشتغل اليوم (المفتوح عندي حسب الأولوية)، وشو معيقني (المهام المعاقة أو اللي ما تحرّكت). خليه 6 أسطر بالكتير. إذا في قناة فريق مربوطة ابعته عليها بـ notify_post.": "Напиши мой стендап: что сделано вчера (task_list за последние 24 часа и issue_search по моим изменившимся задачам), что делаю сегодня (открытые задачи по приоритету) и что мешает (заблокированные или застрявшие задачи). Не больше шести строк. Если подключён канал команды, отправь туда через notify_post.",
  "كل جمعة 16:00": "По пятницам в 16:00",
  "ملاحظات الإصدار الأسبوعية": "Еженедельные заметки о выпуске",
  "اجمع المهام اللي تسكّرت هالأسبوع من كل الحسابات (issue_search: بـ Jira «resolved >= -7d»، بـ GitHub «is:closed closed:>=تاريخ-قبل-أسبوع»، وبالباقي حسب لغته) واكتب ملاحظات إصدار مرتبة حسب: ميزات، إصلاحات، تحسينات — جملة لكل وحدة مع مفتاحها. ابعتها لقناة الفريق إذا في وحدة مربوطة.": "Собери задачи, закрытые за неделю во всех аккаунтах (issue_search: в Jira «resolved >= -7d», в GitHub «is:closed closed:>=дата-неделю-назад», в остальных — на их языке) и напиши заметки о выпуске по группам: функции, исправления, улучшения — по строке с ключом. Отправь в канал команды, если он подключён.",
  "نكزة المتأخر": "Напоминание о просрочке",
  "كل يوم 14:00": "Каждый день в 14:00",
  "تذكير بالمهام المتأخرة": "Напоминание о просроченных задачах",
  "شوف المهام المسندة إلي اللي استحقاقها فات أو بكرا (issue_list). إذا في، اعرضها مع اقتراح: أخلصها، أأجلها، أو أقسمها (issue_split). لا تعدّل شي بدون ما أطلب.": "Проверь мои задачи с прошедшим или завтрашним сроком (issue_list). Если есть — перечисли с советом: закончить, отложить или разбить (issue_split). Ничего не меняй без моей просьбы.",
  "انعملت «{0}»": "Создано «{0}»",
  "جاهزات": "Готовые",
  "مهام مجدولة بتستعمل حساباتك المربوطة — اضغط وحدة وبتنعمل، وبتعدّلها أو توقفها من المهام ← المجدولة.": "Задачи по расписанию на основе подключённых аккаунтов — нажмите, чтобы создать; изменить или остановить можно в Задачи → По расписанию.",
