  "اقتراحاتك": "Предложения",
  "رفيق بيكبر من اللي بتطلبوه. اكتب اقتراحك أو المشكلة اللي صادفتك، وابعتها على GitHub أو بالإيميل — كل رسالة بتنقرا.": "Rafiq растёт из ваших просьб. Опишите предложение или проблему и отправьте через GitHub или по почте — читаем каждое сообщение.",
