  "GitHub بيفتح صفحة الاقتراح جاهزة — بدها حساب GitHub، والاقتراحات هناك عامة. الإيميل بيفتح برنامج الإيميل عندك برسالة جاهزة لـ {0}.": "GitHub откроет готовое предложение — нужен аккаунт GitHub, и предложения там публичные. Почта откроет ваш почтовый клиент с готовым письмом на {0}.",
