  "امسح الفهرس": "Очистить индекс",
  "انقل كل ملف جديد للمجلد المناسب جوّا التنزيلات حسب نوعه (صور، مستندات، برامج، مضغوط…). ما تحذف شي.": "Перемести каждый новый файл в подходящую папку внутри Загрузок по типу (изображения, документы, программы, архивы…). Ничего не удаляй.",
  "بتسأله «وين فاتورة شهر 3؟» فبيلاقيها من اللي مكتوب جوّاها. الفهرس على جهازك بس، وما بيطلع منه شي.": "Спросите «где счёт за март?» — и он найдёт его по содержимому. Индекс хранится только на вашем компьютере, ничего не уходит наружу.",
