  "كل نسخة بتبدأ مهمة وبتصرف توكنز — اختار نوع النص بدقة. رفيق بيستنى شوي بين مهمة ومهمة، وما بيبدأ أكتر من 30 بالساعة.": "Каждое копирование запускает задачу и тратит токены — выбирайте тип текста точно. Rafiq делает паузы между задачами и запускает не больше 30 в час.",
