  "ما في صوت عربي على ويندوز، فالعربي بينقرأ بالصوت المحلي (إعدادات الفيديو) أو بصوت OpenAI إذا عندك نموذج منه. أو نزّل صوت من إعدادات ويندوز ← الوقت واللغة ← الكلام.": "В Windows нет арабского голоса, поэтому арабский текст читается локальным голосом (настройки видео) или голосом OpenAI, если у вас есть модель OpenAI. Или добавьте голос в Параметрах Windows → Время и язык → Речь.",
